没有考虑如果最后块为无效块的情况，建议进行如下修改：

```
    __aicore__ inline void Reset(const ConstInfo &const_info,int32_t s1_start_idx, int32_t s1_len, int32_t &cur_s1_idx, int32_t &cur_s1_len, __gm__ uint8_t *sparse_mask
    , int32_t b_idx, int32_t n1_idx, int32_t s2Idx)
    {
        this->is_finish_ = false;
        this->s1_start_idx_ = s1_start_idx;
        this->s1_end_idx_ = s1_start_idx + s1_len;
        this->Update(const_info, cur_s1_idx, cur_s1_len, sparse_mask, b_idx, n1_idx, s2Idx);
    }

    __aicore__ inline void Update(const ConstInfo &const_info, int32_t &cur_s1_idx, int32_t &cur_s1_len, __gm__ uint8_t *sparse_mask,  int32_t b_idx, int32_t n1_idx, int32_t s2Idx)
    {
        /*
         *  Single块内只遍历S1方向。
         */
        cur_s1_idx = this->s1_start_idx_;
        cur_s1_len = this->s1_start_idx_ + s1_base_size_ < this->s1_end_idx_ ?
                         s1_base_size_ :
                         (this->s1_end_idx_ - this->s1_start_idx_);

        this->s1_start_idx_ += cur_s1_len;


        int32_t q_block_idx = this->s1_start_idx_ / const_info.block_x;
        int32_t kv_block_idx = s2Idx / const_info.block_y;

        while (true) {
            if (IsValidBlock(const_info, b_idx, n1_idx, q_block_idx, kv_block_idx,
                         sparse_mask)){
                break;
            }
            int32_t tmp_s1_len = this->s1_start_idx_ + s1_base_size_ < this->s1_end_idx_ ?
                                    s1_base_size_ :
                                    (this->s1_end_idx_ - this->s1_start_idx_);
            this->s1_start_idx_ += tmp_s1_len;
            q_block_idx = this->s1_start_idx_ / const_info.block_x;

            if (this->s1_start_idx_ >= this->s1_end_idx_) {
                break;
            }
        }

        if (this->s1_start_idx_ >= this->s1_end_idx_) {
            this->is_finish_ = true;
        }
    }
